// Machine-tool knob — fluted finger-grip skirt + shank with a chamfered,
// domed crown + shaft bore.
// Strategy: fillet/chamfer each primitive BEFORE fusing or cutting so OCCT's
// solver works on simple edge graphs; then fuse, cut the flutes and the bore,
// and finally chamfer the bore rim.
const { BREP } = api;

// Skirt: wide low disc (r 20, 6 mm) with both outer rims rounded. World-Z:
// bottom rim at z=0, top rim at z=6. One-sided filters (maxZ for bottom, minZ
// for top) — symmetric slab filters confuse OCCT's edge selector on a cylinder.
const skirt = BREP.cylinder(20, 6)
  .fillet(1.8, { maxZ: 0.001 })   // bottom outer rim
  .fillet(1.8, { minZ: 5.999 });  // top outer rim

// Shank: column rising from the skirt, 16 mm tall (flat top at z=22). A 3.5 mm
// 45-degree chamfer bevels its top edge (revolved profile — an exact bevel; the
// edge-selector chamfer failed on this cylinder), then a shallow spherical cap domes the
// crown on top of the bevel (cap radius R is chosen so its base is exactly the
// chamfered top face, r 10.5, and it rises 1.5 mm — crown peak at z=23.5).
const shank = BREP.revolve([
  [0, 5], [14, 5], [14, 18.5], [10.5, 22], [0, 22],   // 3.5 mm 45-degree top chamfer
]);

const capBaseR = 10.5;
const capH = 1.5;
const sphereR = (capBaseR * capBaseR + capH * capH) / (2 * capH);
const dome = BREP.sphere(sphereR)
  .translate([0, 0, 22 + capH - sphereR])
  .intersect(BREP.cylinder(capBaseR, 6).translate([0, 0, 21]));

// Fuse skirt + shank + dome — the rounded, chamfered body before grip/bore.
const body = skirt.fuse(shank).fuse(dome);

// Finger-grip flutes: 14 vertical scallops cut around the skirt's rim. Each
// cutter is a r 3 cylinder centred on r 21.5, so it bites 1.5 mm deep into the
// r 20 skirt (down to r 18.5, still well clear of the r 14 shank) and runs the
// full skirt height, scalloping through both rim fillets.
const flute = BREP.cylinder(3, 10).translate([0, 0, -2]);
const flutes = BREP.circularPattern(flute, 14, { radius: 21.5 });
const gripped = body.cut(flutes);

// Bore: 6 mm diameter (r=3), bored from the crown down to z=6 (a press-fit
// shaft hole into the shank, not all the way through). Starts above the crown
// so the boolean produces a clean rim.
const bore = BREP.cylinder(3, 21).translate([0, 0, 6]);
const withBore = gripped.cut(bore);

// Chamfer the resulting bore rim (the entry-easing bevel every machined shaft
// hole gets). minZ 23 selects only the bore-rim circle on the dome.
const knob = withBore.chamfer(0.5, { minZ: 23 });

return BREP.label(knob, 'knob', { color: '#c0392b' });
